// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _test(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 0;
        vm.assume(address(this).balance >= amount);
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint ownerBefore = owner.balance;
        uint cBefore = address(c).balance;
        try c.go{value: amount}() {} catch { return; }
        assertTrue(owner.balance - ownerBefore == cBefore);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}
